1. //! Minimal derrick command-line interface for T008.
2. 
3. #![allow(clippy::print_stdout)]
4. #![allow(clippy::print_stderr)]
5. 
6. use std::ffi::OsString;
7. use std::path::{Path, PathBuf};
8. use std::process::ExitCode;
9. 
10. use clap::{CommandFactory, Parser};
11. use commands::{Cli, Command};
12. use thiserror::Error;
13. 
14. mod commands;
15. mod exit_code;
16. mod output;
17. mod telemetry;
18. 
19. /// Runs the CLI with an argument iterator and returns the process exit code.
20. pub async fn run<I, T>(args: I) -> ExitCode
21. where
22.     I: IntoIterator<Item = T>,
23.     T: Into<OsString> + Clone,
24. {
25.     let cli = match Cli::try_parse_from(args) {
26.         Ok(cli) => cli,
27.         Err(error) => {
28.             let code = error.exit_code();
29.             if let Err(print_error) = error.print() {
30.                 eprintln!("failed to print clap error: {print_error}");
31.             }
32.             return exit_code::from_i32(code);
33.         }
34.     };
35. 
36.     match dispatch(cli).await {
37.         Ok(code) => code.into(),
38.         Err(error) => {
39.             eprintln!("{error}");
40.             ExitCode::from(1)
41.         }
42.     }
43. }
44. 
45. async fn dispatch(cli: Cli) -> Result<exit_code::CliExitCode, CliError> {
46.     match cli.command {
47.         Command::Add(args) => commands::add::execute(args).await,
48.         Command::Init(args) => commands::init::execute(args).await,
49.         Command::Status(args) => commands::status::execute(args).await,
50.         Command::Doctor(args) => commands::doctor::execute(args).await,
51.         Command::Run(args) => commands::run::execute(args).await,
52.         Command::Completions(args) => {
53.             commands::completions::execute(args, &mut Cli::command());
54.             Ok(exit_code::CliExitCode::Success)
55.         }
56.         Command::Ticket(args) => commands::ticket::execute(args).await,
57.         Command::Foreman(args) => commands::foreman::execute(args).await,
58.         Command::Stack(args) => commands::stack::execute(args).await,
59.         Command::Observe(args) => commands::observe::execute(args).await,
60.         Command::Uninstall(args) => commands::uninstall::execute(args).await,
61.         Command::Scrub(args) => commands::scrub::run(args)
62.             .await
63.             .map(|()| exit_code::CliExitCode::Success)
64.             .map_err(|error| message(error.to_string())),
65.         Command::Caveman(args) => commands::caveman::run(args)
66.             .await
67.             .map(|()| exit_code::CliExitCode::Success)
68.             .map_err(|error| message(error.to_string())),
69.         Command::Gain(args) => commands::gain::run(args)
70.             .await
71.             .map(|()| exit_code::CliExitCode::Success)
72.             .map_err(|error| message(error.to_string())),
73.         Command::Switch(args) => commands::switch::execute(args).await,
74.     }
75. }
76. 
77. #[derive(Debug, Error)]
78. enum CliError {
79.     #[error("{0}")]
80.     Message(String),
81.     #[error("IO error at {path}: {source}")]
82.     Io {
83.         path: PathBuf,
84.         source: std::io::Error,
