1. //! `derrick switch --mode <mode>` — upgrade or downgrade an existing repo's
2. //! substrate mode in-place, updating `derrick.yaml` without a full re-init.
3. //!
4. //! Typical usage:
5. //!   derrick switch --mode crew           # solo → crew
6. //!   derrick switch --mode solo           # crew → solo
7. //!   derrick switch --mode crew --dry-run # preview only
8. 
9. use std::io::IsTerminal;
10. use std::path::Path;
11. 
12. use crate::commands::init::{available_model_ids, nested_mapping, recommended_role_bindings};
13. use crate::commands::InitMode;
14. use crate::exit_code::CliExitCode;
15. use crate::{current_repo_root, message, write_file};
16. 
17. /// Changes accumulated during a mode switch, used both for dry-run output
18. /// and for the final confirmation summary.
19. #[derive(Debug)]
20. struct SwitchChanges {
21.     old_mode: String,
22.     new_mode: String,
23.     /// Pipeline step ids that were added (e.g. bridge, foreman).
24.     steps_added: Vec<String>,
25.     /// Steps that are present but incompatible with the new mode and were
26.     /// removed (e.g. bridge/foreman when going back to solo).
27.     steps_removed: Vec<String>,
28.     /// Role assignments that changed: `(role, old_model, new_model)`.
29.     role_changes: Vec<(String, String, String)>,
30. }
31. 
32. pub(crate) async fn execute(
33.     args: crate::commands::SwitchArgs,
34. ) -> Result<CliExitCode, crate::CliError> {
35.     let repo_root = current_repo_root()?;
36.     let config_path = repo_root.join("derrick.yaml");
37. 
38.     if !config_path.exists() {
39.         return Err(message("derrick.yaml not found — run `derrick init` first"));
40.     }
41. 
42.     let raw = std::fs::read_to_string(&config_path).map_err(|source| crate::CliError::Io {
43.         path: config_path.clone(),
44.         source,
45.     })?;
46. 
47.     let mut yaml: serde_yaml::Value =
48.         serde_yaml::from_str(&raw).map_err(|e| message(e.to_string()))?;
49. 
50.     // ── Validate current mode ──────────────────────────────────────────────
51. 
52.     let current_mode = current_mode_str(&yaml);
53.     let target_mode = args.mode.as_str();
54. 
55.     if current_mode == target_mode {
56.         let styled = std::io::stdout().is_terminal() && std::env::var_os("NO_COLOR").is_none();
57.         if styled {
58.             println!(
59.                 "  \x1b[33m·\x1b[0m  Already in \x1b[1m{target_mode}\x1b[0m mode — nothing to do."
60.             );
61.         } else {
62.             println!("  ·  Already in {target_mode} mode — nothing to do.");
63.         }
64.         return Ok(CliExitCode::Success);
65.     }
66. 
67.     // ── Guard: in-flight runs ──────────────────────────────────────────────
68. 
69.     if !args.force {
70.         let inflight = detect_inflight_runs(&repo_root);
71.         if !inflight.is_empty() {
72.             let list = inflight.join(", ");
73.             return Err(message(format!(
74.                 "Cannot switch mode while runs are in flight: {list}\n\
75.                  Wait for them to finish or use --force to override (dangerous)."
76.             )));
77.         }
78.     }
79. 
80.     // ── Compute changes ───────────────────────────────────────────────────
81. 
82.     let changes = compute_changes(&mut yaml, current_mode.clone(), args.mode)?;
83. 
84.     // ── Dry run ───────────────────────────────────────────────────────────
85. 
86.     if args.dry_run {
87.         print_dry_run(&changes);
88.         return Ok(CliExitCode::Success);
89.     }
90. 
91.     // ── Apply ─────────────────────────────────────────────────────────────
92. 
93.     let updated = serde_yaml::to_string(&yaml).map_err(|e| message(e.to_string()))?;
94.     write_file(&config_path, &updated)?;
95. 
96.     print_summary(&changes);
97.     Ok(CliExitCode::Success)
98. }
99. 
100. // ── Helpers ───────────────────────────────────────────────────────────────────
101. 
102. /// Returns the current `tools.substrate.mode` string, defaulting to "solo".
103. fn current_mode_str(yaml: &serde_yaml::Value) -> String {
104.     yaml.get("tools")
105.         .and_then(|t| t.get("substrate"))
106.         .and_then(|s| s.get("mode"))
107.         .and_then(serde_yaml::Value::as_str)
108.         .unwrap_or("solo")
109.         .to_owned()
110. }
111. 
112. /// Returns run-ids (directory names) of runs whose manifest has no
113. /// `finished_at`, indicating they are still in progress.
114. fn detect_inflight_runs(repo_root: &Path) -> Vec<String> {
115.     let runs_dir = repo_root.join(".derrick").join("runs");
116.     let mut inflight = Vec::new();
117.     let Ok(entries) = std::fs::read_dir(&runs_dir) else {
118.         return inflight;
119.     };
120.     for entry in entries.flatten() {
121.         let manifest = entry.path().join("manifest.json");
122.         if !manifest.exists() {
123.             continue;
124.         }
125.         let Ok(text) = std::fs::read_to_string(&manifest) else {
126.             continue;
127.         };
128.         let Ok(json) = serde_json::from_str::<serde_json::Value>(&text) else {
129.             continue;
130.         };
131.         // A run is in-flight when finished_at is absent or explicitly null.
132.         let finished = json
133.             .get("finished_at")
134.             .map(|v| !v.is_null())
135.             .unwrap_or(false);
136.         if !finished {
137.             if let Some(name) = entry.file_name().to_str() {
138.                 inflight.push(name.to_owned());
139.             }
140.         }
141.     }
142.     inflight
143. }
144. 
145. /// Mutates `yaml` in-place to apply the mode switch and returns a summary of
146. /// what changed.
147. fn compute_changes(
148.     yaml: &mut serde_yaml::Value,
149.     old_mode: String,
150.     target: InitMode,
151. ) -> Result<SwitchChanges, crate::CliError> {
152.     let target_str = target.as_str().to_owned();
153.     let root = yaml
154.         .as_mapping_mut()
155.         .ok_or_else(|| message("derrick.yaml is not a YAML mapping"))?;
156. 
157.     // ── 1. Update substrate mode ───────────────────────────────────────────
158.     {
159.         let tools = nested_mapping(root, "tools")?;
160.         let substrate = nested_mapping(tools, "substrate")?;
161.         substrate.insert(
162.             serde_yaml::Value::String("mode".to_owned()),
163.             serde_yaml::Value::String(target_str.clone()),
164.         );
165.     }
166. 
167.     // ── 2. Pipeline steps ─────────────────────────────────────────────────
168.     let (steps_added, steps_removed) = update_pipeline(root, target)?;
169. 
170.     // ── 3. Role recommendations ───────────────────────────────────────────
171.     let role_changes = update_roles(root, target)?;
172. 
173.     Ok(SwitchChanges {
174.         old_mode,
175.         new_mode: target_str,
176.         steps_added,
177.         steps_removed,
178.         role_changes,
179.     })
180. }
181. 
182. /// Adds crew-specific steps (bridge, foreman) when going to crew, removes them
183. /// when leaving crew. Returns `(added, removed)` step id lists.
184. fn update_pipeline(
185.     root: &mut serde_yaml::Mapping,
186.     target: InitMode,
187. ) -> Result<(Vec<String>, Vec<String>), crate::CliError> {
188.     let mut added = Vec::new();
189.     let mut removed = Vec::new();
190. 
191.     let pipeline_key = serde_yaml::Value::String("pipeline".to_owned());
192.     let Some(pipeline_value) = root.get_mut(&pipeline_key) else {
193.         return Ok((added, removed));
194.     };
195.     let Some(steps) = pipeline_value.as_sequence_mut() else {
196.         return Ok((added, removed));
197.     };
198. 
199.     match target {
200.         InitMode::Crew => {
201.             // Add bridge if absent.
202.             if !steps
203.                 .iter()
204.                 .any(|s| crate::commands::init::step_id(s) == Some("bridge"))
205.             {
206.                 steps.push(crate::commands::init::yaml_step(&[
207.                     ("id", "bridge"),
208.                     ("runner", "derrick"),
209.                 ]));
210.                 added.push("bridge".to_owned());
211.             }
212.             // Add foreman if absent.
213.             if !steps
214.                 .iter()
215.                 .any(|s| crate::commands::init::step_id(s) == Some("foreman"))
216.             {
217.                 let mut step =
218.                     crate::commands::init::yaml_step(&[("id", "foreman"), ("runner", "derrick")]);
219.                 if let Some(m) = step.as_mapping_mut() {
220.                     m.insert(
221.                         serde_yaml::Value::String("executor_role".to_owned()),
222.                         serde_yaml::Value::String("executor".to_owned()),
223.                     );
224.                 }
225.                 steps.push(step);
226.                 added.push("foreman".to_owned());
227.             }
228.         }
229.         InitMode::Solo | InitMode::Copilot => {
230.             // Remove bridge and foreman when leaving crew mode.
231.             let crew_steps = ["bridge", "foreman"];
232.             let before = steps.len();
233.             steps.retain(|s| {
234.                 let id = crate::commands::init::step_id(s);
235.                 !id.map(|i| crew_steps.contains(&i)).unwrap_or(false)
236.             });
237.             for id in &crew_steps {
238.                 if steps.len() < before {
239.                     removed.push((*id).to_owned());
240.                 }
241.             }
242.         }
243.     }
244. 
245.     Ok((added, removed))
246. }
247. 
248. /// Updates role assignments to match the recommended defaults for the target
249. /// mode, but only when a role's current model is also a default candidate
250. /// (i.e. it hasn't been customised). Returns the list of changes.
251. fn update_roles(
252.     root: &mut serde_yaml::Mapping,
253.     target: InitMode,
254. ) -> Result<Vec<(String, String, String)>, crate::CliError> {
255.     let mut changes = Vec::new();
256. 
257.     // Determine which models are available in this repo's config.
258.     let available = {
259.         let mut models: std::collections::BTreeMap<String, &'static str> =
260.             std::collections::BTreeMap::new();
261.         if let Some(m) = root
262.             .get(serde_yaml::Value::String("models".to_owned()))
263.             .and_then(serde_yaml::Value::as_mapping)
264.         {
265.             for key in m.keys() {
266.                 if let Some(id) = key.as_str() {
267.                     // Look up against the known catalogue.
268.                     if let Some(description) = available_model_ids().get(id).copied() {
269.                         models.insert(id.to_owned(), description);
270.                     }
271.                 }
272.             }
273.         }
274.         models
275.     };
276. 
277.     let recommended = recommended_role_bindings(target, &available);
278. 
279.     let roles_key = serde_yaml::Value::String("roles".to_owned());
280.     let Some(roles_val) = root.get_mut(&roles_key) else {
281.         return Ok(changes);
282.     };
283.     let Some(roles) = roles_val.as_mapping_mut() else {
284.         return Ok(changes);
285.     };
286. 
287.     for (role, new_model) in recommended.entries() {
288.         let role_key = serde_yaml::Value::String(role.to_owned());
289.         if let Some(current_val) = roles.get(&role_key) {
290.             let current = current_val.as_str().unwrap_or("").to_owned();
291.             if current != new_model {
292.                 roles.insert(role_key, serde_yaml::Value::String(new_model.to_owned()));
293.                 changes.push((role.to_owned(), current, new_model.to_owned()));
294.             }
295.         }
296.     }
297. 
298.     Ok(changes)
299. }
300. 
301. fn is_styled() -> bool {
302.     std::io::stdout().is_terminal() && std::env::var_os("NO_COLOR").is_none()
303. }
304. 
305. fn print_dry_run(changes: &SwitchChanges) {
306.     let styled = is_styled();
307.     println!();
308.     if styled {
309.         println!("  \x1b[1mDry run — no files will be changed.\x1b[0m");
310.     } else {
311.         println!("  Dry run — no files will be changed.");
312.     }
313.     print_changes(changes, styled);
314.     println!();
315. }
316. 
317. fn print_summary(changes: &SwitchChanges) {
318.     let styled = is_styled();
319.     println!();
320.     if styled {
321.         println!(
322.             "  \x1b[32m✓\x1b[0m  Switched \x1b[1m{}\x1b[0m → \x1b[1m{}\x1b[0m",
323.             changes.old_mode, changes.new_mode
324.         );
325.     } else {
326.         println!("  ✓  Switched {} → {}", changes.old_mode, changes.new_mode);
327.     }
328.     print_changes(changes, styled);
329.     println!();
330.     if styled {
331.         println!(
332.             "  \x1b[36m›\x1b[0m  Run \x1b[1mderrick doctor\x1b[0m to verify the new configuration."
333.         );
334.     } else {
335.         println!("  ›  Run `derrick doctor` to verify the new configuration.");
336.     }
337.     println!();
338. }
339. 
340. fn print_changes(changes: &SwitchChanges, styled: bool) {
341.     println!();
342.     println!(
343.         "  {:<18}  {} → {}",
344.         "mode", changes.old_mode, changes.new_mode
345.     );
346.     let _ = styled; // used below for coloured steps/roles
347. 
348.     if !changes.steps_added.is_empty() {
349.         let list = changes.steps_added.join(", ");
350.         if styled {
351.             println!("  {:<18}  \x1b[32m+{list}\x1b[0m", "pipeline steps");
352.         } else {
353.             println!("  {:<18}  +{list}", "pipeline steps");
354.         }
355.     }
356.     if !changes.steps_removed.is_empty() {
357.         let list = changes.steps_removed.join(", ");
358.         if styled {
359.             println!("  {:<18}  \x1b[31m-{list}\x1b[0m", "pipeline steps");
360.         } else {
361.             println!("  {:<18}  -{list}", "pipeline steps");
362.         }
363.     }
364.     for (role, old, new) in &changes.role_changes {
365.         if styled {
366.             println!(
367.                 "  {:<18}  {role}: \x1b[33m{old}\x1b[0m → \x1b[32m{new}\x1b[0m",
368.                 "role"
369.             );
370.         } else {
371.             println!("  {:<18}  {role}: {old} → {new}", "role");
372.         }
373.     }
374. }
