182. /// Adds crew-specific steps (bridge, foreman) when going to crew, removes them
183. /// when leaving crew. Returns `(added, removed)` step id lists.
184. fn update_pipeline(
185.     root: &mut serde_yaml::Mapping,
186.     target: InitMode,
187. ) -> Result<(Vec<String>, Vec<String>), crate::CliError> {
188.     let mut added = Vec::new();
189.     let mut removed = Vec::new();
190. 
191.     let pipeline_key = serde_yaml::Value::String("pipeline".to_owned());
192.     let Some(pipeline_value) = root.get_mut(&pipeline_key) else {
193.         return Ok((added, removed));
194.     };
195.     let Some(steps) = pipeline_value.as_sequence_mut() else {
196.         return Ok((added, removed));
197.     };
198. 
199.     match target {
200.         InitMode::Crew => {
201.             // Add bridge if absent.
202.             if !steps
203.                 .iter()
204.                 .any(|s| crate::commands::init::step_id(s) == Some("bridge"))
205.             {
206.                 steps.push(crate::commands::init::yaml_step(&[
207.                     ("id", "bridge"),
208.                     ("runner", "derrick"),
209.                 ]));
210.                 added.push("bridge".to_owned());
211.             }
212.             // Add foreman if absent.
213.             if !steps
214.                 .iter()
215.                 .any(|s| crate::commands::init::step_id(s) == Some("foreman"))
216.             {
217.                 let mut step =
218.                     crate::commands::init::yaml_step(&[("id", "foreman"), ("runner", "derrick")]);
219.                 if let Some(m) = step.as_mapping_mut() {
220.                     m.insert(
221.                         serde_yaml::Value::String("executor_role".to_owned()),
222.                         serde_yaml::Value::String("executor".to_owned()),
223.                     );
224.                 }
225.                 steps.push(step);
226.                 added.push("foreman".to_owned());
227.             }
228.         }
229.         InitMode::Solo | InitMode::Copilot => {
230.             // Remove bridge and foreman when leaving crew mode.
231.             let crew_steps = ["bridge", "foreman"];
232.             let before = steps.len();
233.             steps.retain(|s| {
234.                 let id = crate::commands::init::step_id(s);
235.                 !id.map(|i| crew_steps.contains(&i)).unwrap_or(false)
236.             });
237.             for id in &crew_steps {
238.                 if steps.len() < before {
239.                     removed.push((*id).to_owned());
240.                 }
241.             }
242.         }
243.     }
244. 
245.     Ok((added, removed))
246. }
